from datetime import date, timedelta

from db import session

STATUSES = ("draft", "sent", "paid")


def add_client(name, email="", company=""):
    with session() as conn:
        cur = conn.execute(
            "INSERT INTO clients (name, email, company) VALUES (?, ?, ?)",
            (name.strip(), email.strip(), company.strip()),
        )
        return cur.lastrowid


def list_clients():
    with session() as conn:
        return conn.execute("SELECT * FROM clients ORDER BY name").fetchall()


def delete_client(client_id):
    with session() as conn:
        count = conn.execute(
            "SELECT COUNT(*) FROM invoices WHERE client_id = ?", (client_id,)
        ).fetchone()[0]
        if count:
            return False
        conn.execute("DELETE FROM clients WHERE id = ?", (client_id,))
        return True


def create_invoice(client_id, issued, due, items, tax_rate=0.0, status="sent"):
    with session() as conn:
        last = conn.execute("SELECT COALESCE(MAX(id), 0) FROM invoices").fetchone()[0]
        cur = conn.execute(
            "INSERT INTO invoices (number, client_id, issued, due, status, tax_rate) "
            "VALUES (?, ?, ?, ?, ?, ?)",
            (f"INV-{last + 1:04d}", client_id, issued, due, status, tax_rate),
        )
        invoice_id = cur.lastrowid
        for item in items:
            conn.execute(
                "INSERT INTO items (invoice_id, description, qty, unit_price) "
                "VALUES (?, ?, ?, ?)",
                (invoice_id, item["description"], item["qty"], item["unit_price"]),
            )
        return invoice_id


def get_invoice(invoice_id):
    with session() as conn:
        row = conn.execute(
            "SELECT invoices.*, clients.name AS client_name, clients.email AS client_email "
            "FROM invoices JOIN clients ON clients.id = invoices.client_id "
            "WHERE invoices.id = ?",
            (invoice_id,),
        ).fetchone()
        if row is None:
            return None
        items = conn.execute(
            "SELECT * FROM items WHERE invoice_id = ?", (invoice_id,)
        ).fetchall()
    data = dict(row)
    data["items"] = [dict(i) for i in items]
    data.update(compute_totals(data["items"], data["tax_rate"]))
    data["overdue"] = is_overdue(data)
    return data


def list_invoices(status=None):
    with session() as conn:
        ids = [r["id"] for r in conn.execute("SELECT id FROM invoices ORDER BY id DESC")]
    invoices = [get_invoice(i) for i in ids]
    if status == "overdue":
        return [i for i in invoices if i["overdue"]]
    if status:
        return [i for i in invoices if i["status"] == status]
    return invoices


def set_status(invoice_id, status):
    if status not in STATUSES:
        raise ValueError(f"bad status: {status}")
    with session() as conn:
        conn.execute("UPDATE invoices SET status = ? WHERE id = ?", (status, invoice_id))


def delete_invoice(invoice_id):
    with session() as conn:
        conn.execute("DELETE FROM invoices WHERE id = ?", (invoice_id,))


def dashboard():
    invoices = list_invoices()
    overdue = [i for i in invoices if i["overdue"]]
    return {
        "outstanding": round(sum(i["total"] for i in invoices if i["status"] == "sent"), 2),
        "paid": round(sum(i["total"] for i in invoices if i["status"] == "paid"), 2),
        "overdue_count": len(overdue),
        "overdue_total": round(sum(i["total"] for i in overdue), 2),
        "recent": invoices[:5],
    }


def compute_totals(items, tax_rate):
    subtotal = sum(i["unit_price"] for i in items)
    tax = subtotal * tax_rate / 100
    return {
        "subtotal": round(subtotal, 2),
        "tax": round(tax, 2),
        "total": round(subtotal + tax, 2),
    }


def is_overdue(invoice):
    return invoice["status"] == "sent" and invoice["due"] < date.today().isoformat()


def default_due(issued, days=14):
    return (date.fromisoformat(issued) + timedelta(days=days)).isoformat()

