from datetime import date

from flask import Flask, abort, flash, redirect, render_template, request, url_for

import db
import services

app = Flask(__name__)
app.secret_key = "dev-only-change-me"


def parse_items(form):
    items = []
    rows = zip(form.getlist("description"), form.getlist("qty"), form.getlist("unit_price"))
    for desc, qty, price in rows:
        if not desc.strip():
            continue
        try:
            items.append({
                "description": desc.strip(),
                "qty": float(qty or 1),
                "unit_price": float(price or 0),
            })
        except ValueError:
            continue
    return items


@app.route("/")
def index():
    stats = services.dashboard()
    return render_template("index.html", stats=stats, invoices=stats["recent"])


@app.route("/clients")
def clients():
    return render_template("clients.html", clients=services.list_clients())


@app.route("/clients/new", methods=["GET", "POST"])
def client_new():
    if request.method == "POST":
        name = request.form["name"].strip()
        if not name:
            flash("Name is required.")
        else:
            services.add_client(name, request.form.get("email", ""), request.form.get("company", ""))
            flash("Client added.")
            return redirect(url_for("clients"))
    return render_template("client_form.html")


@app.route("/clients/<int:client_id>/delete", methods=["POST"])
def client_delete(client_id):
    if services.delete_client(client_id):
        flash("Client deleted.")
    else:
        flash("Can't delete a client who has invoices.")
    return redirect(url_for("clients"))


@app.route("/invoices")
def invoices():
    status = request.args.get("status")
    return render_template("invoices.html", invoices=services.list_invoices(status))


@app.route("/invoices/new", methods=["GET", "POST"])
def invoice_new():
    if request.method == "POST":
        items = parse_items(request.form)
        if not items:
            flash("Add at least one line item.")
        else:
            issued = request.form.get("issued") or date.today().isoformat()
            due = request.form.get("due") or services.default_due(issued)
            invoice_id = services.create_invoice(
                int(request.form["client_id"]), issued, due, items,
                tax_rate=float(request.form.get("tax_rate") or 0),
            )
            flash("Invoice created.")
            return redirect(url_for("invoice_detail", invoice_id=invoice_id))
    return render_template(
        "invoice_form.html", clients=services.list_clients(), today=date.today().isoformat()
    )


@app.route("/invoices/<int:invoice_id>")
def invoice_detail(invoice_id):
    invoice = services.get_invoice(invoice_id)
    if invoice is None:
        abort(404)
    return render_template("invoice_detail.html", invoice=invoice)


@app.route("/invoices/<int:invoice_id>/status", methods=["POST"])
def invoice_status(invoice_id):
    try:
        services.set_status(invoice_id, request.form["status"])
    except ValueError:
        abort(400)
    return redirect(url_for("invoice_detail", invoice_id=invoice_id))


@app.route("/invoices/<int:invoice_id>/delete", methods=["POST"])
def invoice_delete(invoice_id):
    services.delete_invoice(invoice_id)
    flash("Invoice deleted.")
    return redirect(url_for("invoices"))


@app.route("/api/summary")
def api_summary():
    stats = services.dashboard()
    stats.pop("recent")
    return stats


if __name__ == "__main__":
    db.init_db()
    app.run(debug=True)

{% extends "base.html" %}
{% block content %}
<h1>Dashboard</h1>
<div class="cards">
  <div class="card"><span>Outstanding</span><strong>{{ "%.2f"|format(stats.outstanding) }}</strong></div>
  <div class="card"><span>Paid</span><strong>{{ "%.2f"|format(stats.paid) }}</strong></div>
  <div class="card warn"><span>Overdue ({{ stats.overdue_count }})</span><strong>{{ "%.2f"|format(stats.overdue_total) }}</strong></div>
</div>
<h2>Recent invoices</h2>
{% include "_invoice_table.html" %}
{% endblock %}

{% if invoices %}
<table>
  <tr><th>Number</th><th>Client</th><th>Due</th><th>Status</th><th class="num">Total</th></tr>
  {% for inv in invoices %}
  <tr>
    <td><a href="{{ url_for('invoice_detail', invoice_id=inv.id) }}">{{ inv.number }}</a></td>
    <td>{{ inv.client_name }}</td>
    <td>{{ inv.due }}</td>
    <td><span class="badge {{ 'overdue' if inv.overdue else inv.status }}">{{ 'overdue' if inv.overdue else inv.status }}</span></td>
    <td class="num">{{ "%.2f"|format(inv.total) }}</td>
  </tr>
  {% endfor %}
</table>
{% else %}
<p class="empty">No invoices yet.</p>
{% endif %}

{% extends "base.html" %}
{% block content %}
<h1>Clients</h1>
<p><a class="button" href="{{ url_for('client_new') }}">Add client</a></p>
{% if clients %}
<table>
  <tr><th>Name</th><th>Company</th><th>Email</th><th></th></tr>
  {% for c in clients %}
  <tr>
    <td>{{ c.name }}</td>
    <td>{{ c.company }}</td>
    <td>{{ c.email }}</td>
    <td>
      <form method="post" action="{{ url_for('client_delete', client_id=c.id) }}">
        <button class="link">Delete</button>
      </form>
    </td>
  </tr>
  {% endfor %}
</table>
{% else %}
<p class="empty">No clients yet.</p>
{% endif %}
{% endblock %}

