{% block content %}
<h1>New invoice</h1>
{% if not clients %}
<p class="empty">Add a <a href="{{ url_for('client_new') }}">client</a> first.</p>
{% else %}
<form method="post">
  <label>Client
    <select name="client_id">
      {% for c in clients %}<option value="{{ c.id }}">{{ c.name }}</option>{% endfor %}
    </select>
  </label>
  <label>Issued <input type="date" name="issued" value="{{ today }}"></label>
  <label>Due (blank = 14 days) <input type="date" name="due"></label>
  <label>Tax % <input name="tax_rate" value="0"></label>
  <h2>Line items</h2>
  {% for n in range(4) %}
  <div class="row">
    <input name="description" placeholder="Description">
    <input name="qty" placeholder="Qty" value="1">
    <input name="unit_price" placeholder="Unit price">
  </div>
  {% endfor %}
  <button>Create invoice</button>
</form>
{% endif %}
{% endblock %}

